def normalise_phones(apps, schema_editor):
    """Existing numbers -> 2547XXXXXXXX. Numbers that aren't Kenyan mobiles, and the
    second account using the same number, are cleared (printed so you can follow up)."""
    from accounts.phone import normalize_ke_phone
    User = apps.get_model("accounts", "User")
    seen = set()
    for u in User.objects.order_by("date_joined"):
        raw = u.phone
        n = normalize_ke_phone(raw) if raw else None
        if n and n in seen:
            print(f"\n  phone {raw} cleared on {u.email}: already used by an older account")
            n = None
        elif raw and not n:
            print(f"\n  phone {raw!r} cleared on {u.email}: not a Kenyan mobile number")
        if n:
            seen.add(n)
        if u.phone != n:
            u.phone = n
            u.save(update_fields=["phone"])


